from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an arithmetic expression tree."""
    match e:
        case Num(v):
            return v
        case Add(l, r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l, r):
            return eval_expr(l) * eval_expr(r)


def test_eval_num() -> None:
    assert eval_expr(Num(42)) == 42
    assert eval_expr(Num(-7)) == -7
    assert eval_expr(Num(0)) == 0


def test_eval_add() -> None:
    assert eval_expr(Add(Num(3), Num(4))) == 7
    assert eval_expr(Add(Num(-3), Num(4))) == 1


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(3), Num(4))) == 12
    assert eval_expr(Mul(Num(-3), Num(4))) == -12
    assert eval_expr(Mul(Num(5), Num(0))) == 0


def test_eval_nested() -> None:
    # 1 + (2 * 3) = 7
    tree1 = Add(Num(1), Mul(Num(2), Num(3)))
    assert eval_expr(tree1) == 7

    # (1 + 2) * (3 + 4) = 21
    tree2 = Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))
    assert eval_expr(tree2) == 21

    # ((2 * 3) + (4 * 5)) * 2 = (6 + 20) * 2 = 52
    tree3 = Mul(Add(Mul(Num(2), Num(3)), Mul(Num(4), Num(5))), Num(2))
    assert eval_expr(tree3) == 52

